class Solution {
public:
    int kSimilarity(string s1, string s2) {
        if (s1 == s2) return 0;
        queue<pair<string, int>> q;
        unordered_set<string> visited;
        q.push({s1, 0});
        visited.insert(s1);
        int n = s1.length();
        while (!q.empty()) {
            auto [curr, step] = q.front();
            q.pop();
            int i = 0;
            while (i < n && curr[i] == s2[i]) i++;
            for (int j = i + 1; j < n; j++) {
                if (curr[j] == s2[i] && curr[j] != s2[j]) {
                    string nxt = curr;
                    swap(nxt[i], nxt[j]);
                    if (nxt == s2) return step + 1;
                    if (!visited.count(nxt)) {
                        visited.insert(nxt);
                        q.push({nxt, step + 1});
                    }
                    if (curr[i] == s2[j]) break;
                }
            }
        }
        return -1;
    }
};

class Solution {
    public int kSimilarity(String s1, String s2) {
        if (s1.equals(s2)) return 0;
        Queue<String> q = new LinkedList<>();
        Set<String> visited = new HashSet<>();
        q.offer(s1);
        visited.add(s1);
        int step = 0;
        int n = s1.length();
        while (!q.isEmpty()) {
            int sz = q.size();
            for (int k = 0; k < sz; k++) {
                String curr = q.poll();
                if (curr.equals(s2)) return step;
                int i = 0;
                while (i < n && curr.charAt(i) == s2.charAt(i)) i++;
                for (int j = i + 1; j < n; j++) {
                    if (curr.charAt(j) == s2.charAt(i) && curr.charAt(j) != s2.charAt(j)) {
                        char[] arr = curr.toCharArray();
                        char tmp = arr[i];
                        arr[i] = arr[j];
                        arr[j] = tmp;
                        String nxt = new String(arr);
                        if (!visited.contains(nxt)) {
                            visited.add(nxt);
                            q.offer(nxt);
                        }
                        if (curr.charAt(i) == s2.charAt(j)) break;
                    }                }
            }
            step++;
        }
        return -1;
    }
}

var kSimilarity = function(s1, s2) {
    if (s1 === s2) return 0;
    const q = [[s1, 0]];
    const visited = new Set([s1]);
    const n = s1.length;
    while (q.length > 0) {
        const [curr, step] = q.shift();
        let i = 0;
        while (i < n && curr[i] === s2[i]) i++;
        for (let j = i + 1; j < n; j++) {
            if (curr[j] === s2[i] && curr[j] !== s2[j]) {
                const arr = curr.split('');
                const tmp = arr[i];
                arr[i] = arr[j];
                arr[j] = tmp;
